import { $,esc,icon,mount,heading,empty,field,busy,toast,confirmDialog,back } from '../ui.js';
import {listEvents,allRows,profileData,preferences,updateProfile,signedUrls,uploadImage,signOut,api,deadline} from '../data.js';
import {enableNotifications} from '../timer.js';
export const dateLabel=date=>new Date(`${date}T12:00:00`).toLocaleDateString(undefined,{day:'numeric',month:'long',year:'numeric'});
export function eventCard(event){const d=new Date(`${event.date}T12:00:00`);return `<a class="glass event-card" href="event.html?id=${encodeURIComponent(event.id)}"><div class="date-tile"><b>${d.getDate()}</b><small>${esc(d.toLocaleDateString(undefined,{month:'short'}).toUpperCase())}</small></div><div class="grow"><h3>${esc(event.title)}</h3><p>${esc(event.location||dateLabel(event.date))}</p></div>${event.is_priority?'<span class="badge rose">Priority</span>':icon('chevron')}</a>`}
export async function renderPage(page,root,user){if(page==='profile')return profile(root,user);if(page==='settings')return settings(root,user);const events=await listEvents(user);if(page==='events'||page==='memories')return eventsPage(root,events,page==='memories');if(page==='calendar')return calendar(root,user,events);return home(root,user,events)}
async function home(root,user,events){const upcoming=events.filter(e=>e.status!=='past').sort((a,b)=>deadline(a)-deadline(b));const next=upcoming[0];const profile=profileData(user);let tasks=[],images={};if(next){[tasks,images]=await Promise.all([allRows('tasks',q=>q.eq('event_id',next.id)),signedUrls('event-images',[next.image_path])])}const done=tasks.filter(t=>t.completed).length;const percent=tasks.length?Math.round(done/tasks.length*100):0;
mount(root,heading('MAKE SPACE FOR WHAT MATTERS',`Hello, ${profile.nickname||profile.name||'you'}.`,'A little preparation. A more present you.')+(!preferences(user).notifications&&!sessionStorage.getItem('prelude-banner-dismissed')?`<div class="notice row"><div class="grow"><strong>A gentle reminder, right on time.</strong><p>Enable notifications for your events and timers.</p></div><button class="text-btn" id="enablePush">Enable</button><button class="icon-btn" id="dismissPush" aria-label="Dismiss notification reminder">×</button></div>`:'')+(next?`<a class="glass hero" href="event.html?id=${encodeURIComponent(next.id)}"><div class="hero-cover">${images[next.image_path]?`<img src="${esc(images[next.image_path])}" alt="">`:'<div class="hero-art"></div>'}<div class="hero-meta row between"><span class="badge rose">YOUR NEXT MOMENT</span>${next.is_priority?'<span class="badge">Priority</span>':''}</div><div class="hero-title"><span class="date">${esc(dateLabel(next.date))}</span><h2>${esc(next.title)}</h2><p>${esc(next.location||'Make this moment yours.')}</p></div></div><div class="hero-bottom"><div class="countdown" id="countdown"></div><div class="row between section"><small>Preparation</small><small>${done} of ${tasks.length} tasks · ${percent}%</small></div><div class="progress"><span style="width:${percent}%"></span></div></div></a>`:empty('Your next chapter starts here.','Give something you’re looking forward to a name and a date.','create.html'))+`<section class="section"><div class="section-head"><h2>Coming up</h2><a href="events.html">View all ${icon('chevron')}</a></div><div class="stack">${upcoming.slice(1,4).map(eventCard).join('')||'<p class="muted">Room for your next meaningful moment.</p>'}</div></section>`);
if(next){const tick=()=>{const seconds=Math.max(0,Math.floor((window.PreludeHomeData.eventStart({...next,time:next.time||'09:00:00'})-Date.now())/1000));$('#countdown').innerHTML=seconds?[[Math.floor(seconds/86400),'DAYS'],[Math.floor(seconds%86400/3600),'HOURS'],[Math.floor(seconds%3600/60),'MINUTES']].map(([n,l])=>`<div class="unit"><b>${String(n).padStart(2,'0')}</b><small>${l}</small></div>`).join(''):'<span class="badge rose">Your moment is here</span>'};tick();const interval=setInterval(tick,30000);window.addEventListener('pagehide',()=>clearInterval(interval),{once:true})}if($('#enablePush'))$('#enablePush').onclick=busy($('#enablePush'),async()=>{await enableNotifications(user);location.reload()});if($('#dismissPush'))$('#dismissPush').onclick=()=>{sessionStorage.setItem('prelude-banner-dismissed','1');$('.notice').remove()}}
function eventsPage(root,events,past){let query='';function render(){mount(root,heading('YOUR MOMENTS',past?'Remember.':'Everything ahead.','Your plans, gathered in one place.')+`<div class="segmented" role="group" aria-label="Event filter"><button id="upcoming" class="${!past?'active':''}" aria-pressed="${!past}">Upcoming</button><button id="past" class="${past?'active':''}" aria-pressed="${past}">Past</button></div><input class="search" id="eventSearch" type="search" placeholder="Find an event" aria-label="Search events" value="${esc(query)}"><div class="stack" id="eventList"></div>`);const filter=()=>{const rows=events.filter(e=>(e.status==='past')===past&&e.title.toLowerCase().includes(query.toLowerCase()));$('#eventList').innerHTML=rows.map(eventCard).join('')||empty(past?'Memories take time.':'Nothing here yet.',past?'Completed events will live here.':'Create an event to start preparing.',past?'':'create.html')};filter();$('#upcoming').onclick=()=>{past=false;render()};$('#past').onclick=()=>{past=true;render()};$('#eventSearch').oninput=e=>{query=e.target.value;filter()}}render()}
async function profile(root,user){const data=profileData(user);const events=await listEvents(user);const image=await signedUrls('avatars',[data.avatarPath]);mount(root,back('index.html')+heading('YOUR SPACE','A little more you.')+`<section class="glass pad"><div class="identity-card"><div class="portrait">${image[data.avatarPath]?`<img src="${esc(image[data.avatarPath])}" alt="Your profile photo">`:esc((data.nickname||user.email||'P').slice(0,1).toUpperCase())}</div><div class="grow"><h1>${esc(data.nickname||data.name)}</h1><p>${esc(user.email)}</p></div></div><div class="stats"><div><strong>${events.length}</strong><small>Events</small></div><div><strong>${events.filter(e=>e.status!=='past').length}</strong><small>Upcoming</small></div><div><strong>${events.filter(e=>e.status==='past').length}</strong><small>Memories</small></div></div></section><form class="glass pad stack section" id="profileForm">${field('Full name','name','text',data.name,'required maxlength="80" autocomplete="name"')}${field('What should we call you?','nickname','text',data.nickname,'required maxlength="40"')}${field('Profile photo','photo','file','','accept="image/jpeg,image/png,image/webp"')}<small>JPG, PNG or WebP · up to 8 MB</small><button class="btn primary" type="submit">Save profile</button></form><a class="glass settings-row pad section" href="settings.html"><span class="row-icon">${icon('settings')}</span><div class="grow"><p>Settings</p><small>Make Prelude feel at home.</small></div>${icon('chevron')}</a>`);$('#profileForm').onsubmit=busy($('#profileForm button'),async()=>{const form=$('#profileForm');const changes={name:form.name.value.trim(),nickname:form.nickname.value.trim()};if(!changes.name||!changes.nickname)throw {friendly:'Please enter your name and preferred name.'};if(form.photo.files[0])changes.avatarPath=await uploadImage(user,'avatars',form.photo.files[0]);user=await updateProfile(user,changes);toast('Profile saved.');await profile(root,user)})}
async function settings(root,user){const p=preferences(user);const zones=Intl.supportedValuesOf?Intl.supportedValuesOf('timeZone'):[p.timezone,'Africa/Lagos','UTC'];if(!zones.includes(p.timezone))zones.unshift(p.timezone);const countries=['NG','GH','KE','ZA','US','GB','CA','AU','IN','DE','FR'];if(!countries.includes(p.holidayCountry))countries.unshift(p.holidayCountry);const names=new Intl.DisplayNames(undefined,{type:'region'});mount(root,back('profile.html')+heading('MAKE IT YOURS','Settings.','Thoughtful defaults. A few personal touches.')+`<form class="glass pad stack" id="settingsForm">${field('Account email','email','email',user.email,'disabled')}<label>Default event timezone<select name="timezone">${zones.map(z=>`<option ${z===p.timezone?'selected':''}>${esc(z)}</option>`).join('')}</select></label><small>Existing events keep their original timezone.</small><label>Public holiday country<select name="country">${countries.map(c=>`<option value="${c}" ${c===p.holidayCountry?'selected':''}>${esc(names.of(c))}</option>`).join('')}</select></label><label class="row"><input type="checkbox" name="warning" ${p.hideCreationWarning?'checked':''}>Skip the name and date confirmation when creating events</label><button class="btn primary">Save preferences</button></form><div class="glass pad section"><div class="settings-row"><span class="row-icon">${icon('bell')}</span><div class="grow"><p>Notifications</p><small>${p.notifications?'Enabled for this account.':'Event reminders and timer alerts.'}</small></div><button class="btn sm" id="notifications">${p.notifications?'Disable':'Enable'}</button></div><div class="settings-row"><span class="row-icon">${icon('lock')}</span><div class="grow"><p>Password</p><small>We’ll email you a secure reset link.</small></div><button class="text-btn" id="password">Reset</button></div><div class="settings-row"><span class="row-icon">${icon('logout')}</span><div class="grow"><p>Sign out</p><small>Your plans remain saved to your account.</small></div><button class="text-btn danger" id="logout">Sign out</button></div></div><p class="footer-note">PRELUDE · PLAN. LIVE. REMEMBER.</p>`);$('#settingsForm').onsubmit=busy($('#settingsForm button'),async()=>{const form=$('#settingsForm');user=await updateProfile(user,{preferences:{timezone:form.timezone.value,holidayCountry:form.country.value,hideCreationWarning:form.warning.checked}});toast('Preferences saved.')});$('#notifications').onclick=busy($('#notifications'),async()=>{if(!preferences(user).notifications){await enableNotifications(user)}else{await api('/api/push',{method:'DELETE',authenticated:true});await updateProfile(user,{preferences:{notifications:false}})}location.reload()});$('#password').onclick=busy($('#password'),async()=>{const {error}=await supabaseClient.auth.resetPasswordForEmail(user.email,{redirectTo:new URL('reset.html?mode=set',location.href).href});if(error)throw error;toast('Check your email for a reset link.')});$('#logout').onclick=busy($('#logout'),async()=>{if(await confirmDialog('Sign out?','Your events and preparation will be here when you return.','Sign out'))await signOut()})}
async function calendar(root,user,events){let month=new Date();month.setDate(1);let selected=new Date().toLocaleDateString('en-CA');let holidays=[];let holidayMessage='';let generation=0;function render(){const year=month.getFullYear(),m=month.getMonth();const days=new Date(year,m+1,0).getDate();const date=n=>`${year}-${String(m+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`;mount(root,heading('ONE DAY AT A TIME','Your calendar.','Tap to explore. Long-press to plan.')+`<section class="glass pad"><div class="calendar-nav"><button class="icon-btn" id="prev" aria-label="Previous month">${icon('back')}</button><h2>${esc(month.toLocaleDateString(undefined,{month:'long',year:'numeric'}))}</h2><button class="icon-btn" id="next" aria-label="Next month">${icon('arrow')}</button></div><div class="weekdays">${['SUN','MON','TUE','WED','THU','FRI','SAT'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${'<span></span>'.repeat(month.getDay())}${Array.from({length:days},(_,i)=>{const d=date(i+1);return `<button class="calendar-day ${d===selected?'selected':''} ${d===new Date().toLocaleDateString('en-CA')?'today':''} ${events.some(e=>e.date===d)?'has-events':''}" data-date="${d}" aria-label="${dateLabel(d)}" aria-pressed="${d===selected}">${i+1}</button>`}).join('')}</div></section><section class="section stack"><div class="section-head"><h2>${esc(dateLabel(selected))}</h2><a href="create.html?date=${selected}">Create event ${icon('plus')}</a></div>${events.filter(e=>e.date===selected).map(eventCard).join('')||'<p class="muted">A little space in your day.</p>'}${holidays.filter(h=>h.date===selected).map(h=>`<div class="notice"><strong>${esc(h.name||h.localName)}</strong><p>Public holiday</p></div>`).join('')}<small>${esc(holidayMessage)}</small></section>`);$('#prev').onclick=()=>change(-1);$('#next').onclick=()=>change(1);document.querySelectorAll('[data-date]').forEach(button=>{let timer,held=false;button.onclick=()=>{if(held){held=false;return}selected=button.dataset.date;render()};button.onpointerdown=()=>{held=false;timer=setTimeout(()=>{held=true;location.href=`create.html?date=${button.dataset.date}`},650)};for(const name of ['pointerup','pointercancel','pointerleave'])button.addEventListener(name,()=>clearTimeout(timer));button.oncontextmenu=e=>e.preventDefault()})}async function load(){const token=++generation;holidayMessage='Loading public holidays…';render();try{const result=await api(`/api/holidays?country=${preferences(user).holidayCountry}&year=${month.getFullYear()}`,{authenticated:true});if(token!==generation)return;holidays=result.holidays||[];holidayMessage=result.available===false?'Public holidays are unavailable for this country.':''}catch(e){if(token!==generation)return;holidayMessage='Public holidays are unavailable right now.'}render()}function change(amount){month.setMonth(month.getMonth()+amount);load()}await load()}
